43	// The active-ish states that reserve a domain / occupy a node slot.
44	const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
45	
46	/** Least-loaded enabled+online node with account headroom. */
47	async function scheduleHostingNode(): Promise<{ id: string } | null> {
48	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
49	  if (!nodes.length) return null;
50	  const loads = await Promise.all(
51	    nodes.map(async (n) => ({
52	      node: n,
53	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
54	    })),
55	  );
56	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
57	  return withRoom.length ? { id: withRoom[0].node.id } : null;
58	}
