213	function toView(a: {
214	  id: string; primaryDomain: string; status: string; username: string; diskQuotaMB: number; maxSites: number;
215	  maxDatabases: number; sslActive: boolean; phpVersion: string; error: string | null; expiresAt: Date | null; createdAt: Date;
216	  dbToolPath?: string | null;
217	  diskUsedMB?: number | null; inodesUsed?: number | null; usageAt?: Date | null;
218	  serveHttpOk?: boolean | null; serveHttpsOk?: boolean | null; healthNote?: string | null; healthCheckedAt?: Date | null;
219	  plan: { name: string; phpVersions: string }; node: { publicIp: string; hostnameFqdn: string | null };
220	}): HostingAccountView {
221	  const pt = pointToRecords(a.node);
