223	    id: a.id, primaryDomain: a.primaryDomain, planName: a.plan.name, status: a.status, username: a.username,
224	    pointToA: pt.aRecord, pointToCname: pt.cnameTarget, diskQuotaMB: a.diskQuotaMB, maxSites: a.maxSites,
225	    diskUsedMB: a.diskUsedMB ?? null, inodesUsed: a.inodesUsed ?? null, usageAt: a.usageAt?.toISOString() ?? null,
226	    maxDatabases: a.maxDatabases, sslActive: a.sslActive, phpVersion: a.phpVersion,
227	    serveHttpOk: a.serveHttpOk ?? null, serveHttpsOk: a.serveHttpsOk ?? null,
228	    healthNote: a.healthNote ?? null, healthCheckedAt: a.healthCheckedAt?.toISOString() ?? null,
229	    phpVersions: planLimits({ diskGB: 1, maxSites: 1, maxDatabases: 0, bandwidthTB: 0, phpVersions: a.plan.phpVersions }).phpVersions,
230	    dbToolPath: a.dbToolPath ?? null,
231	    error: a.error, expiresAt: a.expiresAt?.toISOString() ?? null, createdAt: a.createdAt.toISOString(),
232	  };
233	}
