270	/**
271	 * Customer "Check now / Go live" — flag an ACTIVE account for an immediate
272	 * serve-verification + SSL recheck. The worker's fast lane (~30s) picks up
273	 * recheckRequested accounts before their routine 10-min cadence, verifies HTTP/
274	 * HTTPS from the node, self-heals a stale cert vhost, and nudges the SSL sweep so a
275	 * trusted certificate can start issuing. Owner or admin; a no-op for non-active
276	 * accounts (nothing to verify until it's provisioned).
277	 */
278	export async function recheckHostingHealth(id: string): Promise<HostingResult> {
279	  const user = await requireUser();
280	  const a = await db.hostingAccount.findUnique({ where: { id }, select: { userId: true, status: true } });
281	  if (!a) return { error: "Not found." };
282	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
283	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
284	  await db.hostingAccount.update({ where: { id }, data: { recheckRequested: true } });
285	  revalidatePath(`/dashboard/hosting/${id}`);
286	  return { ok: true };
287	}
