289	/** Re-queue a FAILED account for the provisioner. Owner or admin. */
290	export async function retryHostingProvision(id: string): Promise<HostingResult> {
291	  const user = await requireUser();
292	  const a = await db.hostingAccount.findUnique({ where: { id } });
293	  if (!a) return { error: "Not found." };
294	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
295	  if (a.status !== "FAILED") return { error: "This account isn’t in a failed state." };
296	  await db.hostingAccount.update({ where: { id }, data: { status: "PENDING", error: null } });
297	  revalidatePath("/dashboard/hosting");
298	  return { ok: true };
299	}
