376	async function ownedActiveAccount(id: string) {
377	  const user = await requireUser();
378	  const a = await db.hostingAccount.findUnique({ where: { id }, include: { plan: true, _count: { select: { databases: true } } } });
379	  if (!a) return { error: "Account not found." as const };
