403	const PHP_RE = /^\d\.\d$/;
404	
405	export async function setHostingPhpVersion(accountId: string, version: string): Promise<HostingResult> {
406	  const ctx = await ownedActiveAccount(accountId);
407	  if ("error" in ctx) return { error: ctx.error };
408	  if (!PHP_RE.test(version) || !planLimits(ctx.a.plan).phpVersions.includes(version)) return { error: "That PHP version isn’t available on your plan." };
409	  await db.hostingTask.create({ data: { accountId, kind: "PHP_SWITCH", payload: JSON.stringify({ version }) } });
410	  revalidatePath("/dashboard/hosting");
411	  return { ok: true };
412	}
