414	export async function installWordPress(accountId: string): Promise<HostingResult> {
415	  const ctx = await ownedActiveAccount(accountId);
416	  if ("error" in ctx) return { error: ctx.error };
417	  const { user, a } = ctx;
418	  if (a._count.databases >= a.maxDatabases) return { error: `WordPress needs a database, but your plan's ${a.maxDatabases} are used. Delete one first.` };
419	  // Generate all creds up front; the worker applies them, then the admin login is
420	  // returned ONCE via the task result.
421	  const dbName = `${a.username}_wp`.slice(0, 64);
422	  const dbUser = dbName.slice(0, 32);
423	  const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
424	  const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
425	  await db.hostingTask.create({
426	    data: {
427	      accountId,
428	      kind: "WORDPRESS_INSTALL",
429	      payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: user.email }),
430	    },
431	  });
432	  revalidatePath("/dashboard/hosting");
433	  return { ok: true };
434	}
