635	// ---------- Subdomains + addon domains + cron (cPanel-class site mgmt) -------
636	// Every value that reaches the node shell is validated here (isValidUnixUsername
637	// / isValidHostingDomain / isValidSubdomainLabel / cron validators) AND re-checked
638	// in the worker. Caps are enforced inside a Serializable transaction so concurrent
639	// creates cannot both read a stale count and blow past the plan (same discipline
640	// as createHostingDatabase). The task is queued in the SAME tx as the row create.
641	
642	const SITE_STATES = ["PENDING", "ACTIVE"] as const;
643	const MAX_CRON_JOBS = 20;
644	
645	/** Owner (or admin) + ACTIVE account, returning the fields the site actions need. */
646	async function ownedSiteAccount(id: string) {
647	  const user = await requireUser();
648	  // Impersonating admins must not create/destroy customer resources — cron is
649	  // arbitrary command execution as the customer's unix user; subdomains/addons
650	  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
651	  await assertNotImpersonating();
652	  const a = await db.hostingAccount.findUnique({
653	    where: { id },
654	    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
655	  });
656	  if (!a) return { error: "Account not found." as const };
657	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
658	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
659	  return { user, a };
660	}
661	
662	/**
663	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
664	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
665	 * subdomain, or an addon domain. Before this, each creator only checked its own
666	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
667	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
668	 * This single check, used by all three creators, is the app-level invariant (no DB
669	 * unique can span three tables + a deliberately re-usable primaryDomain).
670	 */
671	async function isHostnameClaimed(name: string): Promise<boolean> {
672	  const [prim, sub, addon] = await Promise.all([
673	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
674	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
675	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
676	  ]);
677	  return prim + sub + addon > 0;
678	}
