805	  if (!isValidCronSchedule(sched)) return { error: "Enter a valid 5-field cron schedule (e.g. 0 3 * * *)." };
806	  if (!isValidCronCommand(cmd)) return { error: "Enter a command (one line, up to 500 characters, no % character)." };
807	  try {
808	    await db.$transaction(async (tx) => {
809	      const n = await tx.hostingCron.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
810	      if (n >= MAX_CRON_JOBS) throw new Error("CAP");
811	      const cron = await tx.hostingCron.create({ data: { accountId: a.id, schedule: sched, command: cmd, status: "PENDING" } });
812	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_CRON", payload: JSON.stringify({ cronId: cron.id }) } });
813	    }, { isolationLevel: "Serializable" });
814	  } catch (e) {
815	    if (e instanceof Error && e.message === "CAP") return { error: `You can schedule up to ${MAX_CRON_JOBS} cron jobs.` };
816	    return { error: "Couldn’t add the cron job — try again." };
817	  }
818	  revalidatePath(`/dashboard/hosting/${accountId}`);
819	  return { ok: true };
820	}
