/// Which kind of resource a hostname claim reserves. Purely descriptive — the
/// authoritative guarantee is the UNIQUE(hostname) on the claim row itself.
enum HostingClaimKind {
  PRIMARY
  SUBDOMAIN
  ADDON
}

/// Single authoritative registry of every hostname served on the fleet, spanning
/// ALL THREE places a name can live — an account's primary domain, a subdomain,
/// or an addon domain. The UNIQUE(hostname) is the atomic cross-tenant guard: a
/// claim row is inserted in the SAME transaction as the resource row it names, so
/// two concurrent requests that both pass the advisory isHostnameClaimed()
/// pre-check can never both commit the same nginx `server_name` — the second
/// INSERT fails on the unique (Prisma P2002) and rolls its whole transaction back.
/// Before this table there was no single constraint spanning the three hostname
/// tables (primaryDomain has no unique), so co-tenants on one node could shadow
/// each other's vhost (security audit: co-tenant vhost-shadowing TOCTOU). The
/// hostname is stored normalized (trimmed + lowercased) so case/format variants
/// can't dodge the unique. Freed by deleting the row when the resource is removed
/// (same tx as the delete / on account termination); the accountId relation also
/// cascades if the account row is ever hard-deleted.
model HostingHostnameClaim {
  id        String           @id @default(cuid())
  hostname  String           @unique
  accountId String
  account   HostingAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingClaimKind
  createdAt DateTime         @default(now())

  @@index([accountId])
}

